  reply_markup: {"inline_keyboard": [[{"text": "🔎 Углубить", "callback_data": "cmd:deepen"}, {"text": "🧩 В JSON", "callback_data": "cmd:json"}, {"text": "✨ Оптимизировать", "callback_data": "cmd:optimize"}], [{"text": "📝 В Obsidian", "callback_data": "cmd:save"}]]}
}) }}
